// All backend calls of the Item Units page. Docs: ../backend/doc/week1/item-unit.txt
import api from "../../services/api";

// Only the documented fields. `code` is generated by the server and never sent.
function toItemUnitBody(form) {
  return {
    name: form.name.trim(),
  };
}

export async function getItemUnits() {
  const response = await api.get("/item-unit");
  return response.data.data;
}

export async function createItemUnit(form) {
  const response = await api.post("/item-unit", toItemUnitBody(form));
  return response.data.data;
}

export async function updateItemUnit(id, form) {
  const response = await api.patch(`/item-unit/${id}`, toItemUnitBody(form));
  return response.data.data;
}

export async function deleteItemUnit(id) {
  await api.delete(`/item-unit/${id}`);
}
